"""Build a private, standalone review of actual prototype state. No external assets."""
import argparse
import json
from pathlib import Path
from memory import connect,overview

HTML='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Dashboard Job · Arbeitsgedächtnis im Test</title>
<style>
:root{font:16px/1.5 system-ui,sans-serif;color:#192d31;background:#f3f5f3}*{box-sizing:border-box}body{margin:0}main{max-width:1150px;margin:auto;padding:40px 26px}header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px}h1{font-size:34px;letter-spacing:-1px;margin:6px 0}h2{font-size:20px;margin:0 0 16px}h3{font-size:17px;margin:0 0 8px}p{margin:8px 0}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:#4d706a}.muted{font-size:13px;color:#647577}.notice{padding:16px 20px;background:#fff1cf;border:1px solid #e9ce8e;border-radius:12px;margin:22px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:start}.panel{background:white;border:1px solid #dbe4df;border-radius:16px;padding:22px;margin-bottom:22px}.item{padding:16px 0;border-top:1px solid #e3eae6}.item:first-of-type{border-top:0;padding-top:0}.badge{display:inline-block;font-size:12px;padding:3px 8px;background:#e8f2ed;color:#315c51;border-radius:5px;margin:0 6px 7px 0}.warning{background:#fff0d5;color:#8a4b17}details{margin-top:10px}summary{cursor:pointer;color:#3d645a;font-size:14px}blockquote{margin:10px 0;padding:12px 15px;border-left:3px solid #b8ccc4;background:#f5f8f6;white-space:pre-wrap;font-size:13px}select{font:inherit;padding:9px 14px;border:1px solid #bfcec7;background:white;border-radius:8px}.empty{padding:16px;color:#677975;background:#f4f7f4;border-radius:8px}.stats{display:flex;gap:22px;margin:20px 0}.stat b{font-size:26px;display:block}button{font:inherit;background:#163d33;color:white;border:0;border-radius:8px;padding:9px 16px;cursor:pointer}.timeline{font-size:13px;color:#526b63;margin:0 0 10px}footer{font-size:12px;color:#647577}a{color:#315c51}@media(max-width:750px){.grid{grid-template-columns:1fr}header{display:block}h1{font-size:28px}.stats{flex-wrap:wrap}}
</style><main><header><div><div class="eyebrow">Dashboard Job · Isolierter Prototyp</div><h1>Wissen behalten. Arbeit erkennen.</h1><p class="muted">Echte Originalmeetings, belegte Vorgänge und nachvollziehbare Änderungen.</p></div><label>Wissensstand<br><select id="date" aria-label="Wissensstand auswählen"></select></label></header>
<div class="notice"><strong>Entwicklungsstand – keine produktive Aufgabenliste.</strong><p>Diese Ansicht zeigt gespeicherte Modellvorschläge, eine zusätzliche Quellenprüfung und deine bestätigten Korrekturen aus Originalmeetings. Quellen sind technisch geprüft; fachliche Gesamtqualität, Abschlüsse und überholte Zusagen sind noch nicht abgenommen.</p></div>
<div class="stats" id="stats"></div><div class="grid"><section class="panel"><h2>Für mich</h2><div id="personal"></div></section><section class="panel"><h2>Zusagen anderer</h2><div id="waiting"></div></section></div><section class="panel"><h2>Neue Belege nach Vorgang</h2><div id="changes"></div></section><div class="grid"><section class="panel"><h2>Eigene Zusagen mit Voraussetzung</h2><div id="dependencies"></div></section><section class="panel"><h2>Belegt erledigt</h2><div id="completed"></div></section></div><section class="panel"><h2>Vorgänge und belegtes Wissen</h2><p class="muted">Risiken, Voraussetzungen und offene Entscheidungen bleiben beim Thema. Eine Kategorie ist noch kein Beweis für eine richtige Interpretation.</p><div id="matters"></div></section><footer>Nur lokale Testdaten. Keine Verbindung zur produktiven Inbox. Originalbelege wurden unverändert aus den Quellen übernommen. Keine späteren Meetings im früheren Wissensstand.</footer></main>
<script>
const snapshots=DATA;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={commitment:'Zusage',dependency:'Voraussetzung',fact:'Information',decision:'Entscheidung',question:'Offene Frage',risk:'Risiko',idea:'Option',status:'Status'};
function annotation(o){return (o.human_corrections||[]).map(c=>'<p class="badge">Von dir bestätigt: '+esc(c.reason)+'</p>').join('')+(o.work_gate?'<details><summary>Zusätzliche Quellenprüfung</summary><p class="muted">'+esc(o.work_gate.reason)+' · Modellurteil, keine Nutzerbestätigung</p></details>':'')}
function evidence(o){return '<details><summary>Originalbelege ansehen</summary>'+o.quotes.map(q=>'<blockquote>'+esc(q)+'</blockquote>').join('')+'</details>'}
function card(o){return '<article class="item"><span class="badge">'+esc(o.owner||'Keine Zuständigkeit')+'</span>'+(o.due_text?'<span class="badge">'+esc(o.due_text)+' · Bezug '+esc(o.due_reference_date||o.last_changed)+'</span>':'')+'<h3>'+esc(o.title)+'</h3><p>'+esc(o.claim)+'</p><p class="muted">Zuletzt belegt: '+esc(o.last_changed)+'</p>'+annotation(o)+evidence(o)+'</article>'}
function render(){const s=snapshots[document.getElementById('date').value];document.getElementById('completed').innerHTML=s.completed.map(card).join('')||'<p class="empty">Noch kein Abschluss belegt.</p>';document.getElementById('dependencies').innerHTML=s.waiting_dependencies.map(card).join('')||'<p class="empty">Keine eigene wartende Zusage.</p>';const changes={};s.knowledge.filter(r=>r.event_date===s.as_of).forEach(r=>(changes[r.matter_id]??=[]).push(r));document.getElementById('changes').innerHTML=Object.values(changes).map(rows=>'<details class="item"><summary>'+esc(rows[0].matter_title)+' · '+rows.length+' neue Belege</summary>'+rows.map(r=>'<details class="item"><summary>'+esc(names[r.kind])+' · '+esc(r.data.title)+'</summary><p>'+esc(r.data.claim)+'</p>'+annotation(r.data)+evidence(r.data)+'</details>').join('')+'</details>').join('');document.getElementById('personal').innerHTML=s.personal.map(card).join('')||'<p class="empty">Keine persönliche Zusage im ausgewählten Testbestand.</p>';document.getElementById('waiting').innerHTML=s.waiting.map(card).join('')||'<p class="empty">Keine offenen fremden Zusagen.</p>';const groups={};s.knowledge.forEach(r=>(groups[r.matter_id]??=[]).push(r));document.getElementById('stats').innerHTML=[[s.personal.length,'persönliche Zusagen'],[s.waiting.length,'fremde Zusagen'],[Object.keys(groups).length,'Vorgänge'],[s.knowledge.length,'belegte Aussagen']].map(([n,t])=>'<div class="stat"><b>'+n+'</b>'+t+'</div>').join('');document.getElementById('matters').innerHTML=Object.values(groups).map(rows=>'<article class="item"><h3>'+esc(rows[0].matter_title)+'</h3><p class="timeline">'+[...new Set(rows.map(r=>r.event_date))].map(esc).join(' → ')+'</p><details><summary>'+rows.length+' Aussagen und Änderungen</summary>'+rows.map(r=>'<div class="item"><span class="badge">'+esc(names[r.kind])+'</span><span class="muted">'+esc(r.event_date)+'</span><p>'+esc(r.data.claim)+'</p>'+(r.data.uncertainty?'<p class="badge warning">'+esc(r.data.uncertainty)+'</p>':'')+annotation(r.data)+evidence(r.data)+'</div>').join('')+'</details></article>').join('')}
const select=document.getElementById('date');Object.keys(snapshots).forEach(date=>{const o=document.createElement('option');o.value=date;o.textContent=date;select.append(o)});select.value=Object.keys(snapshots).at(-1);select.addEventListener('change',render);render();
</script></html>'''

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--db',default='.local/prototype.sqlite');parser.add_argument('--output',default='.local/review.html');args=parser.parse_args()
    db=connect(args.db);dates=[r[0] for r in db.execute('SELECT DISTINCT event_date FROM observations ORDER BY event_date')]
    snapshots={date:overview(db,date) for date in dates};db.close()
    Path(args.output).write_text(HTML.replace('DATA',json.dumps(snapshots,ensure_ascii=False).replace('<','\\u003c')))
    print(str(Path(args.output).resolve()))
